#!/bin/bash
# hy2-multiroute 一键安装脚本（自包含：面板代码已内嵌）
# 新服务器上 root 执行：bash install.sh
set -e

PANEL_DIR=/opt/hy2-panel
SINGBOX_VER="1.11.15"

[ "$(id -u)" = 0 ] || { echo "请用 root 运行"; exit 1; }

echo "=== 1. 安装系统依赖 ==="
if command -v apt-get >/dev/null; then
  export DEBIAN_FRONTEND=noninteractive
  apt-get update -qq
  apt-get install -y -qq python3 python3-venv openssl curl >/dev/null
elif command -v dnf >/dev/null; then
  dnf install -y -q python3 python3-pip openssl curl >/dev/null
else
  echo "不支持的发行版（需要 apt 或 dnf）"; exit 1
fi

echo "=== 2. 安装 sing-box ==="
ARCH=$(uname -m)
case "$ARCH" in
  x86_64) ARCH="amd64" ;;
  aarch64) ARCH="arm64" ;;
  *) echo "不支持的架构: $ARCH"; exit 1 ;;
esac
if ! command -v sing-box >/dev/null; then
  curl -fsSL -o /tmp/sing-box.tar.gz "https://github.com/SagerNet/sing-box/releases/download/v${SINGBOX_VER}/sing-box-${SINGBOX_VER}-linux-${ARCH}.tar.gz"
  tar -xzf /tmp/sing-box.tar.gz -C /tmp
  cp /tmp/sing-box-*/sing-box /usr/local/bin/
  chmod +x /usr/local/bin/sing-box
fi
sing-box version | head -1

echo "=== 3. 写入面板代码 ==="
mkdir -p "$PANEL_DIR/static"
base64 -d > "$PANEL_DIR/app.py" <<'APP_PY_EOF'

APP_PY_EOF
base64 -d > "$PANEL_DIR/static/index.html" <<'INDEX_EOF'

INDEX_EOF
mkdir -p "$PANEL_DIR/data"

echo "=== 4. Python 虚拟环境 ==="
if [ ! -x "$PANEL_DIR/venv/bin/python" ]; then
  python3 -m venv "$PANEL_DIR/venv"
fi
"$PANEL_DIR/venv/bin/pip" install -q flask

echo "=== 5. 证书（自签） ==="
mkdir -p /etc/hy2
if [ ! -f /etc/hy2/cert.pem ]; then
  openssl ecparam -name prime256v1 -genkey -noout -out /etc/hy2/key.pem
  openssl req -new -x509 -key /etc/hy2/key.pem -out /etc/hy2/cert.pem -days 3650 -subj "/CN=hy2.local"
fi

echo "=== 6. 初始配置 ==="
if [ ! -f /etc/hy2/config.json ]; then
  cat > /etc/hy2/config.json <<'EOF'
{
  "log": { "level": "warn", "timestamp": true },
  "inbounds": [],
  "outbounds": [{ "type": "direct", "tag": "direct" }],
  "route": { "final": "direct" }
}
EOF
fi
sing-box check -c /etc/hy2/config.json && echo "配置校验通过"

echo "=== 7. systemd 服务 ==="
# 公网 IP（供面板生成分享链接）
SERVER_IP=$(curl -fs -m 5 https://api.ipify.org 2>/dev/null || hostname -I | awk '{print $1}')

cat > /etc/systemd/system/hy2.service <<EOF
[Unit]
Description=hy2 multiroute (sing-box)
After=network.target

[Service]
ExecStart=/usr/local/bin/sing-box run -c /etc/hy2/config.json
Restart=always
RestartSec=5
LimitNOFILE=65535
MemoryMax=96M

[Install]
WantedBy=multi-user.target
EOF

cat > /etc/systemd/system/hy2-panel.service <<EOF
[Unit]
Description=hy2 multiroute panel
After=network.target hy2.service

[Service]
WorkingDirectory=$PANEL_DIR
Environment=HY2_SERVER_IP=$SERVER_IP
Environment=PANEL_PORT=5090
ExecStart=$PANEL_DIR/venv/bin/python $PANEL_DIR/app.py
Restart=always
RestartSec=5
MemoryMax=128M

[Install]
WantedBy=multi-user.target
EOF

systemctl daemon-reload
systemctl enable --now hy2 hy2-panel
sleep 1
systemctl is-active hy2 >/dev/null && echo "hy2 服务已启动"
systemctl is-active hy2-panel >/dev/null && echo "hy2-panel 服务已启动"

echo ""
echo "=== 安装完成 ==="
echo "面板地址: http://$SERVER_IP:5090"
echo "默认账号: admin / admin123（登录后请修改密码）"
echo "放行防火墙端口: 5090 (面板) + 面板里添加的入站端口"
